# Load samples
samples_matogrosso_mod13q1 = load_samples(
    name = "samples_matogrosso_mod13q1", 
    package = "sitsdata"
)

rfor_validate_mt = sits_kfold_validate(
    samples = samples_matogrosso_mod13q1,
    folds = 5,
    ml_method = sits_rfor(),
    multicores = 5
)
# plot the confusion matrix
plot(rfor_validate_mt, type_ = "confusion_matrix")
```
